/**
 * The derived XSD inventory of the ASI remainder vocabulary: one entry per kind handle, 61 entries.
 *
 * Generated by `node src/vocab/derive/asi-remainder.ts` over `imsqti_asiv3p0p1_v1p0.xsd` and
 * formatted with `vp fmt`; `src/vocab/derive/asi-remainder.test.ts` checks that a re-run reproduces
 * this file byte for byte. Attribute declarations by `whiteSpace` class over these entries:
 * collapse 212, preserve 81, replace 28, union 2.
 *
 * The remainder is the 51 ASI elements the eleven composed vocabularies hold no kind for: the test
 * structure (20), the companion materials (17), the portable custom interaction (6), the catalog
 * (4), the stimulus (3) and `qti-custom-interaction`. Their 61 kinds add the dotted kinds of the
 * elements with several types, and the test vocabulary's kinds of `qti-rubric-block` and
 * `qti-content-body`.
 *
 * The entries are read from the 3.0.1 XSD. An entry cannot say whether a kind with neither element
 * children nor mixed content holds character data, a wildcard or nothing, nor what 3.0.0 lacks;
 * `src/vocab/asi-remainder.ts` states both, and `src/vocab/derive/asi-remainder.test.ts` checks
 * them against the XSDs.
 *
 * A choice group's members each carry the group's bounds multiplied into their own, so a member of
 * a `(a | b){1..n}` group reads `{ min: 1, max: None }`. The choice groups of two to six members,
 * by entry (the larger groups are the SSML elements and the flow content sets, which carry `0..n`
 * or `1..n`, and the 64 expressions under `qti-branch-rule`, `qti-pre-condition` and
 * `qti-template-default`, which carry `1..1`):
 *
 * - `qti-assessment-section`: (qti-adaptive-selection | qti-selection | qti-ordering){0..1};
 *   (xi:include | qti-assessment-item-ref | qti-assessment-section |
 *   qti-assessment-section-ref){0..n}
 * - `qti-card`: (qti-html-content | qti-file-href | qti-card-entry){1..1}
 * - `qti-protractor`: (qti-increment-si | qti-increment-us){1..1}
 * - `qti-rule`: (qti-rule-system-si | qti-rule-system-us){1..1}
 * - `qti-test-part`: (qti-assessment-section | qti-assessment-section-ref){1..n}
 */
import { Option } from "effect";

import type {
  InventoryAttribute,
  InventoryChild,
  InventoryLeaf,
} from "#pantry/schema/content/xsd-inventory.ts";

/**
 * Build an attribute row from its declaration.
 *
 * @param name - The attribute name as the XSD spells it.
 * @param type - The declared type name, or the base of an inline type.
 * @param use - Whether the XSD requires the attribute.
 * @param family - Which attribute family the name belongs to.
 * @param whiteSpace - The `whiteSpace` class of the declared type.
 * @param defaultValue - The XSD `default`, absent when none is declared.
 * @returns The attribute row.
 */
const attribute = (
  name: string,
  type: string,
  use: InventoryAttribute["use"],
  family: InventoryAttribute["family"],
  whiteSpace: InventoryAttribute["whiteSpace"],
  defaultValue?: string,
): InventoryAttribute => ({
  default: Option.fromNullishOr(defaultValue),
  family,
  name,
  type,
  use,
  whiteSpace,
});

/**
 * Build a child row from an element reference.
 *
 * @param name - The referenced element name as the XSD spells it.
 * @param min - The effective minimum occurrence.
 * @param max - The effective maximum occurrence, `None` when unbounded.
 * @returns The child row.
 */
const child = (name: string, min: number, max: Option.Option<number>): InventoryChild => ({
  max,
  min,
  name,
});

